// Eğitim amaçlı hazır örnekler. Gerçek kişi ve müşteri verisi değildir.
const ornekler = {
  "Eksik evrak": {
    "Konu": "Konut finansmanı başvurum hakkında",
    "Metin": "Merhaba, konut finansmanı başvurum için kimlik fotokopimi ve maaş bordromu ekte gönderiyorum. Tapu fotokopisini henüz tapu müdürlüğünden alamadım, birkaç gün içinde iletebilirim. Başvurum bu hâliyle değerlendirmeye alınabilir mi?",
    "Ekler": "kimlik.pdf, bordro.pdf"
  },
  "Yeni başvuru": {
    "Konu": "Taşıt finansmanı ön başvuru",
    "Metin": "Merhaba, ikinci el bir otomobil için araç finansmanı ön başvurusu yapmak istiyorum. Gelir belgemi ekte gönderiyorum. Araç bedeli yaklaşık 900.000 TL, vadeyi 36 ay düşünüyorum. Sürecin nasıl ilerleyeceğini bildirirseniz sevinirim.",
    "Ekler": "gelir_belgesi.pdf"
  },
  "Durum sorgusu": {
    "Konu": "Başvurumun durumu",
    "Metin": "İyi günler, geçen salı şubenize gelerek ihtiyaç finansmanı başvurusu yapmıştım. Başvurumun hangi aşamada olduğunu öğrenebilir miyim? Teşekkürler.",
    "Ekler": ""
  },
  "Şikâyet": {
    "Konu": "Başvurum için üç haftadır dönüş yok",
    "Metin": "Konut finansmanı başvurumu üç hafta önce yaptım ve bugüne kadar hiçbir dönüş almadım. Telefonla da ulaşamıyorum. Bu durumdan çok rahatsızım, konunun acilen çözülmesini bekliyorum.",
    "Ekler": "kimlik.pdf, bordro.pdf, tapu.pdf"
  }
};
const f = $input.first().json;
const secim = f['Hazır örnek'] || 'Kendim yazacağım';
const o = ornekler[secim] || {};
const konu = (f['Konu'] || o.Konu || '').trim();
const metin = (f['Metin'] || o.Metin || '').trim();
if (!konu || !metin) {
  throw new Error('"Kendim yazacağım" seçtiyseniz konu ve metin alanlarını doldurun, ya da bir hazır örnek seçin.');
}
const simdi = $now.setZone('Europe/Istanbul');
return [{ json: {
  Mesaj_ID: 'FORM-' + simdi.toFormat('yyMMdd-HHmmss'),
  Gonderen: f['Adınız'],
  Gonderen_eposta: f['E-posta adresiniz'],
  Konu: konu,
  Metin: metin,
  Ekler: f['Ekler (dosya adları)'] !== undefined && f['Ekler (dosya adları)'] !== '' ? f['Ekler (dosya adları)'] : (o.Ekler || ''),
  Alinma_tarihi: simdi.toISO(),
  Durum: 'Yeni'
} }];
